import {currencyLabels,unitLabels,enhanceLocale} from './locale-11.mjs';
enhanceLocale();
export const prefs={lang:'fa',mode:'simple',calendar:'persian',zone:'Asia/Tehran',theme:'light'};
try{Object.assign(prefs,JSON.parse(localStorage.getItem('anbar:prefs'))||{})}catch{}
export const persist=()=>{localStorage.setItem('anbar:prefs',JSON.stringify(prefs));applyTheme();if(typeof window!=='undefined')window.dispatchEvent(new CustomEvent('anbar-prefs',{detail:{...prefs}}))};
export const t=k=>{const key=String(k).replace(/_\d+$/,'');return words[key]?.[prefs.lang==='fa'?0:1]||k};
export const currency=v=>currencyLabels[v]?.[prefs.lang==='fa'?0:1]||v;
export const unit=v=>unitLabels[v]?.[prefs.lang==='fa'?0:1]||v;
export function applyTheme(){if(typeof document==='undefined')return;const dark=prefs.theme==='dark'||prefs.theme==='system'&&globalThis.matchMedia?.('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.colorScheme=dark?'dark':'light'}
applyTheme();
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const n=v=>new Intl.NumberFormat(prefs.lang==='fa'?'fa-IR':'en-US',{maximumFractionDigits:6}).format(v);
export const date=v=>{if(!v)return '—';try{return new Intl.DateTimeFormat(prefs.lang==='fa'?'fa-IR':'en-GB',{calendar:prefs.calendar,timeZone:/^\d{4}-\d{2}-\d{2}$/.test(v)?'UTC':prefs.zone,year:'numeric',month:'short',day:'numeric'}).format(new Date(v))}catch{return String(v)}};
export const name=o=>o?(prefs.lang==='fa'?o.name:o.en||o.name):'—';
export const $=s=>document.querySelector(s);
export function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
const errors={'Permission denied':'اجازه انجام این عملیات را ندارید.','Warehouse access denied':'به این انبار دسترسی ندارید.','Insufficient available, unexpired stock':'موجودی قابل استفاده و معتبر کافی نیست.','Lot is required':'شماره سری ساخت را وارد کنید.','Enter one unique serial per unit':'برای هر واحد یک سریال یکتا وارد کنید.','Duplicate SKU or barcode':'کد کالا یا بارکد تکراری است.','Stock changed; create a new count':'پس از شمارش موجودی تغییر کرده است؛ شمارش جدید ثبت کنید.','Invalid username or password':'نام کاربری یا گذرواژه نادرست است.','Password must be 12–256 characters':'گذرواژه باید بین ۱۲ تا ۲۵۶ نویسه باشد.','Enter at least one receipt quantity':'حداقل یک مقدار دریافت وارد کنید.','Count below reserved stock':'مقدار شمارش از رزرو کمتر است.','Serial already in stock or transit':'این سریال قبلاً در موجودی یا کالای در راه ثبت شده است.','Allocated stock unavailable or expired':'کالای تخصیص‌یافته در دسترس نیست یا منقضی شده است.','Owner password incorrect':'گذرواژه مدیر اصلی نادرست است.','Read-only API key':'کلید API فقط اجازه خواندن دارد.','Clear stock before archiving':'برای بایگانی، موجودی کالا باید صفر باشد.','Count reason required':'دلیل اصلاح شمارش را بنویسید.'};
export const errorText=e=>prefs.lang==='fa'?(errorsFa[e.message]||errors[e.message]||(/[\u0600-\u06FF]/.test(e.message)?e.message:'عملیات انجام نشد. اطلاعات واردشده را بررسی کنید و دوباره تلاش کنید.')):e.message;
export function btn(label,action,arg='',primary=false){return `<button type="button" class="${primary?'primary':''}" data-action="${action}" data-arg="${esc(arg)}">${esc(t(label))}</button>`}
export function tag(s){return `<span class="tag ${['featurePartial','low','quarantine','pending','in_transit','part_received','part_dispatched','part_returned'].includes(s)?'warn':['expired','damaged','cancelled','failed'].includes(s)?'bad':['featurePlanned','featureExcluded'].includes(s)?'gray':''}">${esc(t(s))}</span>`}
export function table(heads,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${esc(t(h))}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty">${t('noData')}</div>`}
export const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${t(title)}</h2>${extra}</div>${body}</section>`;
export function field(k,type='text',value='',required=true,extra=''){return `<label>${t(k)}<input name="${esc(k)}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra} ${type==='number'?'min="0" step="0.000001"':''}></label>`}
export function select(k,options,value='',extra=''){return `<label>${t(k)}<select name="${esc(k)}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
export const area=(k,value='',extra='')=>`<label class="full">${t(k)}<textarea name="${k}" ${extra}>${esc(value)}</textarea></label>`;
export function close(){ $('#modal').close();$('#modal').dispatchEvent(new Event('closed')) }
export function show(title,html,submit=null,wide=false){const d=$('#modal');if(d.open)d.close();d.className=wide?'form-wide':'';d.innerHTML=`<header><h2>${esc(t(title))}</h2><button type="button" data-close aria-label="${t('close')}">×</button></header>${submit?`<form><div class="fields">${html}</div><p class="error" role="alert"></p><div class="form-actions"><button type="button" data-close>${t('cancel')}</button><button type="submit" class="primary">${t('save')}</button></div></form>`:html}`;d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);if(submit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await submit(Object.fromEntries(new FormData(e.target)),e.target);close()}catch(err){d.querySelector('.error').textContent=errorText(err)}finally{b.disabled=false}};return d}
export async function api(path,body){let r;try{r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})}catch{if(path==='actions')return enqueue(body);throw Error(t('offline'))}let s;try{s=await r.json()}catch{throw Error(t('offline'))}if(!r.ok)throw Object.assign(Error(s.error||'Request failed'),{status:r.status});return s}
export function download(filename,data,type='text/plain'){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
export function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+(typeof v==='number'?String(v):String(v??'').replace(/^[=+@-]/,"'$&")).replaceAll('"','""')+'"').join(',')).join('\r\n')}
export function parseCSV(text){let rows=[],row=[],cell='',q=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){cell+='"';i++}else q=!q}else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(q)throw Error('Invalid CSV');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
export function chooseFile(accept,callback){const i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=async()=>{try{if(i.files[0].size>12e6)throw Error('Maximum file size: 12 MB');await callback(await i.files[0].text())}catch(e){toast(errorText(e))}};i.click()}
